created = renamed = 0
seen = {}
for addr, base, how in FUNCS:
    a = A(addr)
    fn = fm.getFunctionAt(a)
    if fn is None:
        fn = createFunction(a, None)
        if fn is not None:
            created += 1
    if fn is None:
        continue
    n = seen.get(base, 0) + 1
    seen[base] = n
    try:
        fn.setName("%s_%02d_%08x" % (base, n, addr), SourceType.ANALYSIS)
        fn.setComment("source file: %s (%s)" % (base, how))
        renamed += 1
    except:
        pass

commented = 0
for addr, path, line in SITES:
    cu = listing.getCodeUnitAt(A(addr))
    if cu is not None:
        cu.setComment(CodeUnit.PRE_COMMENT, "%s:%d" % (path, line))
        commented += 1

print("created %d functions, named %d, commented %d file/line sites" % (created, renamed, commented))
